CREATE TABLE "PharmacologySource" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"title" TEXT NOT NULL,"organization" TEXT NOT NULL,"sourceUrl" TEXT,"versionLabel" TEXT,"publishedAt" DATE,"provenanceType" TEXT NOT NULL,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "PharmacologySource_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GenericMedicationFamilyMembership" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"familyId" UUID NOT NULL,"sourceId" UUID,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GenericMedicationFamilyMembership_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MedicationAlias" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"alias" TEXT NOT NULL,"normalizedAlias" TEXT NOT NULL,"aliasType" TEXT NOT NULL DEFAULT 'TRADE_NAME',"scopeType" TEXT NOT NULL DEFAULT 'CLINIC',"scopeId" TEXT,"status" TEXT NOT NULL DEFAULT 'active',"createdByUserId" UUID,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "MedicationAlias_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MechanismSummary" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"sourceId" UUID NOT NULL,"bulletsJson" JSONB NOT NULL,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "MechanismSummary_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PharmacodynamicSummary" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"sourceId" UUID NOT NULL,"bulletsJson" JSONB NOT NULL,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "PharmacodynamicSummary_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PharmacokineticSummary" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"sourceId" UUID NOT NULL,"absorptionJson" JSONB NOT NULL,"metabolismJson" JSONB NOT NULL,"halfLifeJson" JSONB NOT NULL,"eliminationJson" JSONB NOT NULL,"clinicalNotesJson" JSONB NOT NULL,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "PharmacokineticSummary_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AdverseEffect" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"sourceId" UUID NOT NULL,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL,"severity" TEXT NOT NULL,"frequencyCategory" TEXT,"summaryText" TEXT,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AdverseEffect_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Contraindication" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"sourceId" UUID NOT NULL,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL,"classification" TEXT NOT NULL,"summaryText" TEXT,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Contraindication_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Caution" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"sourceId" UUID NOT NULL,"riskGroup" TEXT NOT NULL,"normalizedText" TEXT NOT NULL,"summaryText" TEXT NOT NULL,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Caution_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Interaction" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"primaryGenericId" UUID NOT NULL,"secondaryGenericId" UUID,"sourceId" UUID NOT NULL,"interactingSubstance" TEXT,"normalizedSearchText" TEXT NOT NULL,"severity" TEXT NOT NULL,"mechanismText" TEXT,"recommendedResponse" TEXT NOT NULL,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Interaction_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MonitoringRequirement" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"sourceId" UUID NOT NULL,"parameter" TEXT NOT NULL,"normalizedParameter" TEXT NOT NULL,"timingText" TEXT,"staleAfterHours" INTEGER,"summaryText" TEXT NOT NULL,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MonitoringRequirement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PregnancyLactationProfile" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"sourceId" UUID NOT NULL,"pregnancyNarrative" TEXT NOT NULL,"trimesterJson" JSONB,"reproductiveJson" JSONB,"lactationNarrative" TEXT NOT NULL,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "PregnancyLactationProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RenalGuidance" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"sourceId" UUID NOT NULL,"primaryElimination" TEXT,"activeMetaboliteAccumulation" TEXT,"adjustmentStatus" TEXT NOT NULL,"monitoringText" TEXT,"guidanceJson" JSONB NOT NULL,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RenalGuidance_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HepaticGuidance" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"sourceId" UUID NOT NULL,"primaryMetabolism" TEXT,"adjustmentStatus" TEXT NOT NULL,"monitoringText" TEXT,"guidanceJson" JSONB NOT NULL,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "HepaticGuidance_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AntimicrobialSpectrum" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"medicationGenericId" UUID NOT NULL,"sourceId" UUID NOT NULL,"gramPositive" TEXT NOT NULL DEFAULT 'unknown/unverified',"gramNegative" TEXT NOT NULL DEFAULT 'unknown/unverified',"anaerobic" TEXT NOT NULL DEFAULT 'unknown/unverified',"atypical" TEXT NOT NULL DEFAULT 'unknown/unverified',"pseudomonas" TEXT NOT NULL DEFAULT 'unknown/unverified',"mrsa" TEXT NOT NULL DEFAULT 'unknown/unverified',"enterococcus" TEXT NOT NULL DEFAULT 'unknown/unverified',"esblRelevance" TEXT NOT NULL DEFAULT 'unknown/unverified',"intracellular" TEXT NOT NULL DEFAULT 'unknown/unverified',"resistanceLimitations" TEXT NOT NULL,"reviewStatus" TEXT NOT NULL DEFAULT 'needs_review',"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "AntimicrobialSpectrum_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DoseFormula" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"stableId" TEXT NOT NULL,"medicationGenericId" UUID,"name" TEXT NOT NULL,"calculatorType" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "DoseFormula_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FormulaVersion" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"formulaId" UUID NOT NULL,"version" INTEGER NOT NULL,"expression" TEXT NOT NULL,"outputUnit" TEXT NOT NULL,"inputSchemaJson" JSONB NOT NULL,"validRangeJson" JSONB NOT NULL,"populationText" TEXT NOT NULL,"exclusionsJson" JSONB NOT NULL,"sourceId" UUID NOT NULL,"reviewerUserId" UUID,"approvalStatus" TEXT NOT NULL DEFAULT 'needs_review',"testCasesJson" JSONB NOT NULL,"roundingMethod" TEXT NOT NULL,"limitationsText" TEXT NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "FormulaVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReviewRecord" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"resourceType" TEXT NOT NULL,"resourceId" UUID NOT NULL,"sourceId" UUID,"reviewerUserId" UUID NOT NULL,"decision" TEXT NOT NULL,"reason" TEXT NOT NULL,"reviewedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ReviewRecord_pkey" PRIMARY KEY ("id"));

